insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('reservoircalc', 'intermediate', 'module', 'm01-the-accumulation-is-not-one-tank', 1, 'What does the Professional tier change about the Associate tier''s model of the Ekene field?', '["It rebuilds the structural surfaces so that they honour the fault as a discontinuity.", "It removes the assumption that the accumulation is one connected body of rock.", "It replaces the four constant properties with values that vary from node to node.", "It books the field at three contacts instead of one and reports the range."]'::jsonb, 1, 'The map, the contact, the properties and the chain are all unchanged. One instruction is added: every node is given a block label and the volumes are summed per label.'),
  ('reservoircalc', 'intermediate', 'module', 'm01-the-accumulation-is-not-one-tank', 2, 'A sealing fault is discovered part way through a field study. What happens to the volume of oil in place?', '["It falls, because the compartment on the far side can no longer be drained.", "It rises, because each compartment can hold its own oil column above its own contact.", "Nothing. The rock, the pore space and the oil are all where they were.", "It becomes undefined until a contact has been established in each compartment."]'::jsonb, 2, 'Partitioning a field neither creates nor destroys barrels. What changes is drainage, pressure behaviour and the contact assumption, none of which is a volume.'),
  ('reservoircalc', 'intermediate', 'module', 'm01-the-accumulation-is-not-one-tank', 3, 'Which piece of evidence would most directly establish that a fault seals?', '["A fault trace that is continuous and well imaged across the whole reservoir interval on seismic.", "Original reservoir pressure measured on one side after two years of production on the other.", "A mapped displacement large enough to put reservoir sand against shale at the fault plane.", "Oil water contacts interpreted at the same depth in wells on both sides of the fault."]'::jsonb, 1, 'A connected tank depletes throughout, so undepleted pressure across the fault is direct evidence of a barrier. Juxtaposition is an argument for seal rather than a measurement of it, and matching contacts argue the other way.'),
  ('reservoircalc', 'intermediate', 'module', 'm01-the-accumulation-is-not-one-tank', 4, 'Where does the Ekene fault sit relative to the mapped frame?', '["At an easting of 1800 m, which is fourteen columns in from the western edge.", "At an easting of 1800 m, midway between the two central columns of nodes.", "At an easting of 1900 m, immediately east of the well Ekene-6.", "At the centre of the mapped area, which is why it divides the oil bearing cells almost evenly."]'::jsonb, 0, 'The frame starts at 400 m with 100 m spacing, so 1800 m is column 14 of 25. The split is not close to even: 117 cells west against 52 east.'),
  ('reservoircalc', 'intermediate', 'module', 'm01-the-accumulation-is-not-one-tank', 5, 'How do the six Ekene wells divide between the two blocks?', '["Four west and two east, which is why the western block is better controlled.", "Three each, and all six found oil at the capstone contact.", "Three each, but only one of the three eastern wells found oil at the contact.", "Two west and four east, since the eastern flank needed more appraisal."]'::jsonb, 2, 'Ekene-1, Ekene-3 and Ekene-5 lie west and all found oil. Ekene-6 lies east and found oil; Ekene-2 tops at 1565 m and Ekene-4 at 1590 m, both below the 1560 m contact, so both are dry.'),
  ('reservoircalc', 'intermediate', 'module', 'm01-the-accumulation-is-not-one-tank', 6, 'Why does the western block hold a larger share of the barrels than of the cells?', '["Because its cells were booked against a deeper contact than the eastern cells.", "Because the eastern block loses cells to the extrapolation limit at the frame edge.", "Because it contains the crest, so its oil columns are taller.", "Because net to gross is higher on the western side of the fault."]'::jsonb, 2, 'The properties are identical in both blocks. The west holds 69.2 percent of the cells and 81.2 percent of the barrels because its mean column is 15.4529 m against the east''s 8.0561 m.'),
  ('reservoircalc', 'intermediate', 'module', 'm01-the-accumulation-is-not-one-tank', 7, 'What is the first and cheapest check to run on any partition?', '["That the block cell counts and volumes reproduce the field totals they came from.", "That each block contains at least one well that found oil at its contact.", "That the fault trace on the map falls between two columns of grid nodes.", "That each block''s mean oil column is consistent with its own gross rock volume and cell count."]'::jsonb, 0, 'A partition that loses or gains cells is not a partition. At Ekene, 117 plus 52 gives 169 and the volumes add to the Associate booking.'),
  ('reservoircalc', 'intermediate', 'module', 'm01-the-accumulation-is-not-one-tank', 8, 'Two compartments of a field hold 9.86 and 2.28 MMstb. What is wrong with reporting the field as holding 12.14 MMstb and stopping there?', '["Nothing, provided the two figures are also given in an appendix of the report.", "The sum is arithmetically correct but describes a tank that no single well can drain.", "The sum double counts the cells that lie on the boundary between the compartments.", "The sum is only valid if both compartments were booked against the same contact."]'::jsonb, 1, 'Volumes add. Decisions do not. A sealing fault means no well produces both compartments, so the total is not a drainable volume.'),
  ('reservoircalc', 'intermediate', 'module', 'm01-the-accumulation-is-not-one-tank', 9, 'What does the shade of a cell show on the block explorer map?', '["The block that owns the cell, blue for west and amber for east.", "The porosity assigned to that cell by the property model.", "The oil column at that cell, from a pale sliver to a tall column.", "The distance from that cell to the nearest oil well."]'::jsonb, 2, 'Colour carries the block and shade carries the column. Reading the map for saturation rather than for colour is what makes the block difference obvious.'),
  ('reservoircalc', 'intermediate', 'module', 'm01-the-accumulation-is-not-one-tank', 10, 'Moving the block explorer''s fault control by one step changes what?', '["The number of oil bearing cells in the field and how they are divided.", "Which block owns one column of cells, and nothing else.", "Both the block ownership and the mean oil column of the field.", "The contact against which the eastern block is booked."]'::jsonb, 1, 'The steps match the 100 m grid spacing, so each step moves exactly one column between blocks. The field cell count and the field total cannot move.'),
  ('reservoircalc', 'intermediate', 'module', 'm01-the-accumulation-is-not-one-tank', 11, 'Which of the four properties changes between the Associate and Professional tiers at Ekene?', '["Porosity, which becomes a grid fitted to the six well values.", "Water saturation, which now varies with height above each block''s contact.", "Net to gross, which is lower in the more distal eastern block.", "None. All four remain the constants the tier below was handed."]'::jsonb, 3, 'Net to gross 0.8, porosity 0.20, water saturation 0.35 and a formation volume factor of 1.2 are unchanged. Property variation is the Expert tier''s subject.'),
  ('reservoircalc', 'intermediate', 'module', 'm01-the-accumulation-is-not-one-tank', 12, 'A compartment holds 2.28 MMstb and the field holds 12.14 MMstb. Which question does the compartment figure answer that the field figure cannot?', '["Whether the compartment can support a well of its own.", "Whether the fault between the compartments genuinely seals.", "Whether the mapped surfaces honour the well picks in that compartment.", "Whether the contact used for that compartment is supported by evidence."]'::jsonb, 0, 'Each compartment needs its own well to be produced at all, so the development question is asked per compartment. The other three are not volumetric questions.'),
  ('reservoircalc', 'intermediate', 'module', 'm01-the-accumulation-is-not-one-tank', 13, 'Why is a vertical fault a reasonable approximation at Ekene?', '["Because the fault has no displacement, so the two sides are at the same depth.", "Because the reservoir is about 30 m thick, so a dipping fault moves less than a fifth of a cell.", "Because the grid cells are 100 m square, which is wider than the damage zone of any realistic fault.", "Because the fault seals, and a sealing fault has no measurable dip."]'::jsonb, 1, 'A fault dipping 60 degrees through 30 m of reservoir moves 17 m sideways, which is negligible on a 100 m grid. The same fault through 300 m of reservoir would move nearly two cells.'),
  ('reservoircalc', 'intermediate', 'module', 'm01-the-accumulation-is-not-one-tank', 14, 'Which pair of numbers describes the west block at the capstone settings?', '["117 cells and 9.855617 MMstb.", "130 cells and 10.757040 MMstb.", "52 cells and 2.283591 MMstb.", "169 cells and 12.139208 MMstb."]'::jsonb, 0, 'The pair 130 cells and 10.757040 MMstb is the west block with the boundary column assigned the other way, 52 cells and 2.283591 MMstb is the east block, and 169 cells and 12.139208 MMstb is the whole field.'),
  ('reservoircalc', 'intermediate', 'module', 'm01-the-accumulation-is-not-one-tank', 15, 'What does this tier deliberately leave to the tier below it?', '["The evidence that the fault seals, which volumetrics cannot supply.", "The field booking of 12.139208 MMstb and the numbers that produced it.", "The choice of contact used for each of the two compartments.", "The uncertainty attached to the position of the fault."]'::jsonb, 1, 'The 169 cells, 22.269036 million cubic metres and 12.139208 MMstb belong to the Associate tier and appear here only as checks. The seal evidence comes from outside volumetrics altogether, at any tier.'),
  ('reservoircalc', 'intermediate', 'module', 'm02-labelling-the-grid', 1, 'In what form does the volume engine receive a partition?', '["As a polygon per block, tested against each node''s position at run time.", "As an array of integers, one per node, in the same order as every other grid.", "As a fault easting, which the engine compares against each node in turn.", "As a separate thickness grid per block, with nodes outside the block set null."]'::jsonb, 1, 'The labels are an integer per node. Nothing in the engine limits the number of distinct values, so three faults giving four blocks would need no change to the code.'),
  ('reservoircalc', 'intermediate', 'module', 'm02-labelling-the-grid', 2, 'How does the engine compute the field total when a partition is supplied?', '["It sums the block totals once every node has been visited.", "It takes the largest block''s total and scales it by the cell count ratio.", "It reruns the whole walk a second time with the labels ignored.", "It accumulates it in its own register, in parallel with the blocks."]'::jsonb, 3, 'Each node''s contribution is added twice, once to its block and once to the total. That is why the check that the blocks reproduce the total is a genuine comparison against an independent accumulation.'),
  ('reservoircalc', 'intermediate', 'module', 'm02-labelling-the-grid', 3, 'Which kind of compartment boundary can a label array not represent?', '["A boundary that runs through the middle of a cell rather than along cell edges.", "A boundary that encloses one block completely inside another.", "A boundary that divides the field into more than two compartments.", "A boundary that follows an irregular path instead of a straight line across the frame."]'::jsonb, 0, 'The cell is the atom of the calculation, so a fault crossing a cell diagonally is approximated by giving that whole cell to one side. Nested, multiple and irregular blocks are all expressible.'),
  ('reservoircalc', 'intermediate', 'module', 'm02-labelling-the-grid', 4, 'The Ekene fault at an easting of 1800 m falls exactly on a column of nodes. Why is that not a coincidence?', '["Because the gridder places a node on any fault it is given before it interpolates.", "Because grid origins, cell sizes and quoted fault positions are all round numbers.", "Because the frame is padded by two cells, which always aligns it with the control.", "Because a fault interpreted from seismic is reported to the nearest grid cell."]'::jsonb, 1, 'A grid at 100 m spacing starting on a 100 m multiple has a node on every 100 m easting, so any fault quoted to the nearest hundred metres lands on one. Irregularity only arises when the fault comes from an interpreted surface.'),
  ('reservoircalc', 'intermediate', 'module', 'm02-labelling-the-grid', 5, 'Under the rule this model uses, which block owns a node lying exactly on the fault easting?', '["The west block, because the test is less than or equal to the fault easting.", "Neither. Nodes on the fault are excluded from both blocks and from the total.", "Whichever block already holds the majority of that node''s neighbours.", "The east block, because a node at exactly 1800 m is not strictly less than 1800."]'::jsonb, 3, 'The test is a strict inequality, so the whole boundary column goes east. That is one defensible choice of two, and the other is equally defensible.'),
  ('reservoircalc', 'intermediate', 'module', 'm02-labelling-the-grid', 6, 'How many oil bearing cells lie in the boundary column at an easting of 1800 m?', '["13, carrying 1.653635 million cubic metres of gross rock volume.", "20, since the column runs the full height of the frame.", "117, which is why the west block holds that many cells.", "None, because the fault plane itself is drawn with zero width and contains no reservoir."]'::jsonb, 0, 'The column has 20 nodes and 13 of them carry oil at the 1560 m contact, summing to 165.363525 m of column and about 7.4 percent of the field''s gross rock volume.'),
  ('reservoircalc', 'intermediate', 'module', 'm02-labelling-the-grid', 7, 'What is the tie break convention on the boundary column worth at Ekene?', '["Nothing measurable, since the same cells are counted in the field total either way.", "0.901423 MMstb, transferred between the two compartments.", "0.252229 MMstb, which is the same size as the property model''s spatial effect.", "1.989889 MMstb, the same amount the cross fault control is worth."]'::jsonb, 1, 'West holds 9.855617 MMstb with the column east and 10.757040 with it west. The field total is indeed unchanged, which is exactly why the transfer is easy to miss.'),
  ('reservoircalc', 'intermediate', 'module', 'm02-labelling-the-grid', 8, 'How does the tie break convention compare with the Expert tier''s whole property model?', '["It is about a tenth the size, which is why conventions are rarely reported.", "It is about the same size, so the two deserve equal attention.", "It is larger, at 0.901423 MMstb against 0.656868 MMstb.", "It cannot be compared, since one moves the field total and the other does not."]'::jsonb, 2, 'A tie break in a labelling routine outweighs the entire property model that a whole tier is built around, and only one of the two normally gets a mention in a report.'),
  ('reservoircalc', 'intermediate', 'module', 'm02-labelling-the-grid', 9, 'Which response to a fault landing on a node column is the unreasonable one?', '["Reporting both conventions and treating the gap as part of the uncertainty.", "Refining the grid near the fault so that the misassigned area shrinks.", "Stating the convention explicitly so a reader knows which produced the number.", "Leaving it to the comparison operator in the code and not knowing which way it went."]'::jsonb, 3, 'The rock genuinely straddles the fault and the model cannot split a cell, so reporting both conventions, refining the grid near the fault and stating the convention explicitly are all defensible. Not knowing leaves a 0.9 MMstb question mark that looks like a computed result.'),
  ('reservoircalc', 'intermediate', 'module', 'm02-labelling-the-grid', 10, 'Which nodes in the frame are given a block label?', '["Every node, including dead nodes and nodes that carry no oil.", "Only the 169 nodes that carry an oil column at the contact.", "Only the 201 live nodes, since dead nodes have no position to test.", "Only nodes within 800 m of a well, which is how liveness is decided."]'::jsonb, 0, 'The labelling routine walks all 500 nodes and writes a 0 or a 1 for each. A label is a property of a position, so it exists whether or not anything was mapped there.'),
  ('reservoircalc', 'intermediate', 'module', 'm02-labelling-the-grid', 11, 'A partitioned model is edited and the block cell counts hold while both block volumes fall. What changed?', '["The contact, which has removed column from every cell.", "The fault position, which has relabelled cells between blocks.", "The mapped depths, while the control positions stayed put.", "The property set, which has been revised downward."]'::jsonb, 2, 'Cell counts move when geometry moves and volumes move when depths move. A contact change would have moved the counts and a fault move cannot change the field total.'),
  ('reservoircalc', 'intermediate', 'module', 'm02-labelling-the-grid', 12, 'Why does the live area at Ekene extend smoothly across the fault trace?', '["Because the fault has no displacement, so the surfaces are continuous across it.", "Because the extrapolation limit of 800 m is wider than the fault''s damage zone.", "Because the mask tests distance to control points and knows nothing about faults.", "Because both blocks contain three wells each, so both sides are equally controlled."]'::jsonb, 2, 'The gridder marks a node live if it lies inside the hull or within 800 m of a well. It reads well positions only, so nothing in the mask can respect a partition.'),
  ('reservoircalc', 'intermediate', 'module', 'm02-labelling-the-grid', 13, 'What happens to the field total as the fault is stepped across the whole range?', '["It rises as the fault moves east, because the west block gains taller columns.", "It holds at 12.139208 MMstb at every position.", "It falls at the extremes, where one block holds too few cells to be booked.", "It varies by up to 0.9 MMstb, which is the value of the boundary column."]'::jsonb, 1, 'Moving the fault only relabels cells, so the sum over all cells cannot change. A total that moves during a fault sweep means cells are being counted in more than one block.'),
  ('reservoircalc', 'intermediate', 'module', 'm02-labelling-the-grid', 14, 'At a fault of 1500 m the split is 78 cells west and 91 east; at 1600 m it is 91 and 78. What does that mirror tell you?', '["That the accumulation is close to symmetric in area about an easting near 1550 m.", "That the barrels are also split evenly somewhere between those two positions.", "That the two positions book the same volume in each block.", "That the fault sweep is linear in cell count across the whole range."]'::jsonb, 0, 'The mirror is in area only. The barrels do not mirror, because the western cells carry taller columns, and they split evenly nearer 1450 m.'),
  ('reservoircalc', 'intermediate', 'module', 'm02-labelling-the-grid', 15, 'Why is the eastern block''s volume more uncertain in relative terms than the western block''s?', '["Because it contains two dry wells, which contribute nothing to its mapped surface.", "Because the same absolute transfer is a larger fraction of a smaller block.", "Because its cells lie closer to the extrapolation limit of the mapped area.", "Because its mean oil column is shorter, so each cell''s volume is less certain."]'::jsonb, 1, 'A 100 m move of the fault is worth about 0.9 MMstb either way. That is 10 percent of the west block and around 40 percent of the east, so the smaller compartment carries the larger relative uncertainty.'),
  ('reservoircalc', 'intermediate', 'module', 'm03-the-block-volumes', 1, 'What happens to the volumetric chain when a field is partitioned?', '["It runs once on the larger block and the smaller block is booked by difference.", "It runs once on the field and the result is apportioned by cell count.", "It runs once per block with properties re-averaged over each block separately.", "It runs once per block on that block''s cells, with the same four constants."]'::jsonb, 3, 'The arithmetic is identical. What is new is that the decision maker now has two answers where there was one, and the two are not interchangeable.'),
  ('reservoircalc', 'intermediate', 'module', 'm03-the-block-volumes', 2, 'The west block''s cells and the east block''s cells stand in the ratio 2.25 to 1, and their barrels in the ratio 4.32 to 1. What accounts for the difference?', '["The properties, which the chain applies differently to each block.", "The mean oil column, which is 1.918 times greater in the west.", "The contact, which clips the eastern cells more severely.", "The mask, which removes more eastern cells than western ones."]'::jsonb, 1, 'Area times mean column gives volume, so the volume ratio is the product of the area ratio and the column ratio: 2.25 times 1.918 gives 4.316.'),
  ('reservoircalc', 'intermediate', 'module', 'm03-the-block-volumes', 3, 'Which rows of the partitioned chain reproduce the field total bit for bit?', '["Every row, since a partition is exact arithmetic on the same cells.", "Only the cell count, since only integer addition is exact.", "The cell count, the gross rock volume and the net volume.", "The cell count and the gross rock volume, but not the net volume."]'::jsonb, 2, 'Those three add exactly. Pore volume, hydrocarbon pore volume and STOIIP differ in the last bits, because the chain stops being exactly representable once it multiplies by a float32 porosity.'),
  ('reservoircalc', 'intermediate', 'module', 'm03-the-block-volumes', 4, 'Why does adding the two block STOIIP values not give the field total exactly?', '["Because each block''s STOIIP is rounded to six decimals before being reported.", "Because the blocks and the total are accumulated in separate registers.", "Because the boundary column is counted in the total but in neither block.", "Because the field total is computed from the mean oil column rather than by summing cells."]'::jsonb, 1, 'Floating point addition is not associative. The total sums 169 contributions in node order while the blocks sum 117 and 52 separately, and the two rounding histories differ.'),
  ('reservoircalc', 'intermediate', 'module', 'm03-the-block-volumes', 5, 'How large is the disagreement between the summed blocks and the field STOIIP at Ekene?', '["About 5 parts in a thousand, which is within the capstone tolerance.", "About 5 parts in a million, or roughly six barrels.", "Exactly zero, since the two are computed from the same contributions.", "About 5 parts in 10^15, or roughly five millionths of one barrel."]'::jsonb, 3, 'There is no engineering content in a number that size. The reason for measuring it is to know what clean looks like, so that a genuine discrepancy is recognisable.'),
  ('reservoircalc', 'intermediate', 'module', 'm03-the-block-volumes', 6, 'A three compartment model reports blocks of 5.20, 3.15 and 2.60 MMstb against a field total of 11.00. What does that tell you?', '["Nothing, since the discrepancy of 0.05 MMstb is within normal rounding.", "That the blocks were booked against a different contact from the one the field run used.", "That something structural is wrong, most likely cells belonging to no block.", "That the field total was computed before the partition was applied."]'::jsonb, 2, 'A shortfall of 0.05 MMstb is around 10^13 times larger than the accumulation noise, so it is not floating point. A few cells falling outside every block would produce exactly this.'),
  ('reservoircalc', 'intermediate', 'module', 'm03-the-block-volumes', 7, 'What proportion of the Ekene cells and of the Ekene barrels lies in the west block?', '["There is no fixed proportion, because it depends on the contact.", "81.2 percent of the cells and 69.2 percent of the barrels.", "69.2 percent of both, since the properties are the same in each block.", "69.2 percent of the cells and 81.2 percent of the barrels."]'::jsonb, 3, 'The gap of twelve percentage points is the mean column difference. Whenever those two percentages differ, the blocks hold different shapes of rock.'),
  ('reservoircalc', 'intermediate', 'module', 'm03-the-block-volumes', 8, 'A report gives compartment areas but not compartment volumes. Why is that worse than useless?', '["Because area is intuitive and systematically misleading about where the oil is.", "Because area cannot be converted to volume without knowing net to gross.", "Because the areas will not add to the mapped area of the field.", "Because a compartment''s area depends on the grid cell size that was used."]'::jsonb, 0, 'A block holding a third of the area can hold a fifth of the barrels, or the reverse if it sits on the crest. Either error changes a well count.'),
  ('reservoircalc', 'intermediate', 'module', 'm03-the-block-volumes', 9, 'Where is the tallest oil column in the field at the capstone settings?', '["In the east block, at 16.5079345703125 m near the fault.", "In the west block, at 20.2818603515625 m, the field maximum.", "On the boundary column, where the two blocks meet.", "At Ekene-3, which has the shallowest top pick in the field."]'::jsonb, 1, 'The partition gave the west block the single best cell in the field. The east block''s own maximum of 16.5079345703125 m is 19 percent shorter, and no well produced the field maximum, which is measured from a mapped crest.'),
  ('reservoircalc', 'intermediate', 'module', 'm03-the-block-volumes', 10, 'Why does the block holding the crest inherit more than its share of the uncertainty?', '["Because crestal cells are furthest from well control and therefore least constrained.", "Because the mapped crest is spline overshoot, 1.2819 m shallower than any well pick.", "Because the crest is where the contact assumption bites hardest.", "Because crestal cells carry the largest share of the property uncertainty."]'::jsonb, 1, 'No well found rock as shallow as the mapped crest. The block that holds it holds that artefact in its booking, and it is usually the block whose number is quoted most confidently.'),
  ('reservoircalc', 'intermediate', 'module', 'm03-the-block-volumes', 11, 'The east block''s maximum column is 2.05 times its mean, against 1.31 for the west. What does that say?', '["That the east block is thinner overall than the west block.", "That the east block''s cells are more evenly thick than the west block''s.", "That the east block is much less uniform than the west.", "That the east block''s contact was applied inconsistently across its cells."]'::jsonb, 2, 'A single eastern well placed away from that thick area near Ekene-6 would find far less column than the block maximum suggests. Compartment averages hide that, and this ratio is a cheap way to reveal it.'),
  ('reservoircalc', 'intermediate', 'module', 'm03-the-block-volumes', 12, 'Which reading should be taken first when looking at a partitioned field?', '["The share of barrels against the share of cells, which measures the shape difference.", "Each block''s mean oil column, which is closest to what a well will find.", "Each block''s maximum column against its own mean, which measures uniformity.", "The sum of the blocks against the field total, which is a check rather than a finding."]'::jsonb, 3, 'Check that the partition is a partition before interpreting anything about it. The other three are findings and they are worth nothing if the sum does not close.'),
  ('reservoircalc', 'intermediate', 'module', 'm03-the-block-volumes', 13, 'At a fault of 2000 m the split is 142 cells and 27 cells, with 11.444229 and 0.694979 MMstb. How does that change the development story?', '["It does not, since the field still holds the same 12.139208 MMstb.", "The eastern compartment becomes a sliver very unlikely to justify a well of its own.", "The two compartments become similar enough to be developed as one.", "The western compartment becomes too large to be drained by a single well."]'::jsonb, 1, 'The west now holds 94.3 percent of the barrels. Moving a line 200 m turned a compartment that might carry a well into one that almost certainly cannot.'),
  ('reservoircalc', 'intermediate', 'module', 'm03-the-block-volumes', 14, 'Which of these can this tier answer about a compartmentalised field?', '["Whether the fault between the compartments genuinely seals.", "Whether the smaller compartment is economic to develop.", "What the uncertainty in the fault position is worth in barrels.", "What the contact is in the compartment with no oil bearing well."]'::jsonb, 2, 'A hundred metres of fault position is worth about 0.9 MMstb, which this tier computes. Seal evidence comes from pressure data, economics from another course, and a contact needs a measurement.'),
  ('reservoircalc', 'intermediate', 'module', 'm03-the-block-volumes', 15, 'Which single paragraph is the deliverable of this tier for the Ekene field?', '["That the field holds 12.139208 MMstb across 169 cells at a contact of 1560 m.", "That the fault at 1800 m divides the six Ekene wells evenly, three to each side of the fault trace.", "That the fault at 1800 m divides the six wells evenly, three to each block.", "That a thick, well controlled western compartment holds 9.855617 MMstb and a thin, uneven eastern one holds 2.283591 MMstb."]'::jsonb, 3, 'That description is what somebody planning wells needs. The field total, the well count and the closure check are all true and none of them supports a decision.'),
  ('reservoircalc', 'intermediate', 'module', 'm04-the-fault-the-map-does-not-know', 1, 'In what order was the Ekene compartment model built?', '["The fault was interpreted, then surfaces were gridded within each block separately.", "Surfaces were gridded, the contact was applied, then the labels.", "The labels were assigned first, then each block''s surface was gridded from its own wells.", "The contact was applied to the picks, then surfaces were gridded, then the fault."]'::jsonb, 1, 'At no point did the surface construction know about the fault. The gridder was given six points and a frame and it interpolated across the whole of it.'),
  ('reservoircalc', 'intermediate', 'module', 'm04-the-fault-the-map-does-not-know', 2, 'What does the gridder do at the fault trace?', '["It applies the interpreted displacement as an offset between the two sides.", "It reduces the weight of wells on the far side of the fault.", "It marks the nodes on the trace as dead, leaving a gap on the map.", "It produces a continuous surface with no break of any kind."]'::jsonb, 3, 'A minimum bending surface has no mechanism for producing a discontinuity, and nothing told it one exists. Physically that is unlikely, since a sealing fault usually seals because it has displaced the reservoir.'),
  ('reservoircalc', 'intermediate', 'module', 'm04-the-fault-the-map-does-not-know', 3, 'Ekene-6 is removed from the control set and both surfaces are regridded. What happens to the west block?', '["It loses 34 cells and about a fifth of its area.", "It is unchanged, since Ekene-6 lies in the east block.", "It falls from 9.855617 to 7.865728 MMstb while keeping all 117 cells.", "It falls by about 0.9 MMstb, matching the convention."]'::jsonb, 2, 'A fifth of the western compartment''s booked oil exists in the model only because a well on the far side of a sealing fault pulled the mapped surface up on that side.'),
  ('reservoircalc', 'intermediate', 'module', 'm04-the-fault-the-map-does-not-know', 4, 'Why does the west block keep exactly 117 cells when Ekene-6 is removed?', '["Because Ekene-2 and Ekene-4 lie further east and take over the influence Ekene-6 was supplying.", "Because the liveness test reads well positions only, not what the wells measured.", "Because the contact was held at 1560 m, which fixes the cell count.", "Because cells are assigned to blocks before the surfaces are gridded."]'::jsonb, 1, 'Liveness is geometric. Removing Ekene-6 removes a position, but every western node that was live is live on the strength of the western wells and the hull they form.'),
  ('reservoircalc', 'intermediate', 'module', 'm04-the-fault-the-map-does-not-know', 5, 'Which two features of the geometry make the Ekene-6 effect so large?', '["Its proximity to the fault and the fact that it carries a shallow pick.", "Its distance from the other eastern wells and its low porosity.", "Its position on the hull boundary and its deep base pick.", "Its status as the only eastern well with oil and its high structural position."]'::jsonb, 0, 'It is 100 m from the fault, so its influence on the nodes just west is strong, and at 1546 m it is the second shallowest pick, so removing it lets the surface sag over a wide area.'),
  ('reservoircalc', 'intermediate', 'module', 'm04-the-fault-the-map-does-not-know', 6, 'A partitioned model is edited and the cell counts hold while the volumes move. What changed?', '["The contact, which removed column from every cell in the field.", "The fault position, which relabelled cells between the blocks.", "The mapped depths, while the control positions stayed put.", "The property set, which was revised after the partition was applied."]'::jsonb, 2, 'Cell counts move when geometry moves and volumes move when depths move. A contact change moves the counts and a fault move cannot change the field total.'),
  ('reservoircalc', 'intermediate', 'module', 'm04-the-fault-the-map-does-not-know', 7, 'A colleague''s fault position change increases their field total by 3 percent. What does that mean?', '["The eastern block has absorbed cells that were previously dead ground outside the mapped area.", "There is a bug: relabelling cells cannot change the sum over all cells.", "The fault has moved beyond the eastern limit of the oil bearing area at this contact.", "The blocks are now being booked against different contacts."]'::jsonb, 1, 'Invariance under relabelling is the cheapest check in the set, and it catches cells being counted in more than one block, which is what a mismatched pair of comparison operators produces.'),
  ('reservoircalc', 'intermediate', 'module', 'm04-the-fault-the-map-does-not-know', 8, 'Grid the Ekene surfaces from the three western wells only. What happens?', '["The west block is unchanged and the east block falls to nothing.", "The west block grows, since the eastern picks were pulling its surface down.", "Both blocks shrink by roughly the same proportion.", "The west block falls to 48 cells and the east block to none at all."]'::jsonb, 3, 'With no eastern control no eastern node is within 800 m of a well. More than half of the west block''s mapped area was live only because eastern wells were within reach of it.'),
  ('reservoircalc', 'intermediate', 'module', 'm04-the-fault-the-map-does-not-know', 9, 'How thick does the Ekene reservoir have to be before a vertical fault approximation stops being defensible?', '["Thick enough that the fault''s horizontal offset between top and base approaches the cell size.", "Thick enough that the fault''s displacement exceeds the oil column.", "Thick enough that the base surface falls below the 800 m extrapolation limit set on the grid.", "Thick enough that the two blocks develop different contacts."]'::jsonb, 0, 'A fault dipping 55 degrees through 250 m of reservoir moves 175 m sideways, nearly two cells on a 100 m grid. Through Ekene''s 30 m it moves 17 m, which is negligible.'),
  ('reservoircalc', 'intermediate', 'module', 'm04-the-fault-the-map-does-not-know', 10, 'What is circular about modelling a sealing fault with no displacement?', '["A fault with no displacement cannot be imaged on seismic, so its position is unknown.", "The labels are assigned from the fault position, which was interpreted from the displacement.", "A fault with no displacement has no juxtaposition, so the two blocks must share a contact by construction.", "Sealing is usually produced by displacement, so the model assumes two things that tend to exclude each other."]'::jsonb, 3, 'The model is still useful, because it isolates the partition arithmetic from the mapping question. It is not a picture of a real fault.'),
  ('reservoircalc', 'intermediate', 'module', 'm04-the-fault-the-map-does-not-know', 11, 'How do the six Ekene wells divide by block and by result?', '["Three west and three east, with exactly one dry well in each of the two blocks.", "Three west all oil bearing, three east with only Ekene-6 finding oil.", "Four west all oil bearing, and two east both dry at the 1560 m contact.", "Three west with one dry, three east with two dry."]'::jsonb, 1, 'Ekene-2 tops at 1565 m and Ekene-4 at 1590 m, both below the contact. The east block has three wells and one discovery, and that discovery sits 100 m from the fault.'),
  ('reservoircalc', 'intermediate', 'module', 'm04-the-fault-the-map-does-not-know', 12, 'What do the two dry eastern wells contribute to the model?', '["Nothing, since a dry well cannot inform a volumetric estimate.", "They confirm that the eastern compartment holds no economic oil.", "They define the eastern flank of the structure, so they constrain the surfaces.", "They set the eastern block''s contact, since water was found at 1565 m and 1590 m."]'::jsonb, 2, 'Without them the map would have no idea how fast the surface falls away eastward. What they cannot do is confirm that the eastern compartment holds oil, which only Ekene-6 does.'),
  ('reservoircalc', 'intermediate', 'module', 'm04-the-fault-the-map-does-not-know', 13, 'Which two bookings at Ekene are quoted to the same precision and are not equally certain?', '["The gross rock volume and the net volume of the same block, which differ only by net to gross.", "The field total and the sum of the two blocks.", "The west block''s 9.855617 MMstb and the east block''s 2.283591 MMstb.", "The cell count and the mean oil column of the east block."]'::jsonb, 2, 'The west is supported by three oil bearing wells spread across it with closely agreeing tops. The east is supported by one oil bearing well at its extreme edge, plus two dry wells that constrain the surface and confirm no oil.'),
  ('reservoircalc', 'intermediate', 'module', 'm04-the-fault-the-map-does-not-know', 14, 'Ekene-6 supplies a fifth of the west block''s volume and is the east block''s only proof of oil. What follows?', '["That one well on one side of a sealing fault is load bearing for both compartments.", "That the fault should be moved east so that Ekene-6 falls in the west block.", "That the east block''s booking should be reduced by the amount the west block borrows from it.", "That the two blocks are in communication after all, since they share their well control."]'::jsonb, 0, 'The dependency runs both ways. Moving the fault 200 m east would leave the east block with no oil bearing well at all, which is a large change in confidence for a small change in a line.'),
  ('reservoircalc', 'intermediate', 'module', 'm04-the-fault-the-map-does-not-know', 15, 'Rank the three uncertainties this course has priced on the Ekene west block, largest first.', '["The tie break convention, the fault position, then the cross fault control.", "The cross fault control, the fault position, then the tie break convention.", "The fault position, the cross fault control, then the tie break convention.", "The property model, the cross fault control, then the fault position."]'::jsonb, 1, 'Cross fault control is worth 1.989889 MMstb, the fault position and the tie break about 0.901423 MMstb each, and the whole property model 0.656868 MMstb. Only one of the four normally appears in a report.'),
  ('reservoircalc', 'intermediate', 'module', 'm05-two-blocks-two-contacts', 1, 'Why do two sealed compartments have no obligation to share an oil water contact?', '["Because the fault plane itself holds a separate fluid system between the two blocks.", "Because each compartment has had its own charge history.", "Because the contact is a property of the mapped surface, which steps across a displaced fault.", "Because a sealing fault always juxtaposes different reservoir units against each other."]'::jsonb, 1, 'Compartments that have never been in fluid communication have had independent histories, and there is no mechanism that would force their contacts to agree.'),
  ('reservoircalc', 'intermediate', 'module', 'm05-two-blocks-two-contacts', 2, 'Two compartments are found to share a contact. What does that suggest?', '["That the partition was applied to a map built from a single set of wells.", "That the fault seals only above the contact, where the buoyancy pressure is highest.", "That the compartments were charged from different sources at different times.", "That the fault leaks or leaked, so they equilibrated over geological time."]'::jsonb, 3, 'The alternative is that they were charged to the same fill level independently and their spill points coincide, which happens and is a coincidence rather than a rule.'),
  ('reservoircalc', 'intermediate', 'module', 'm05-two-blocks-two-contacts', 3, 'Take the east block''s contact from 1560 m to 1550 m, holding the west at 1560 m. What happens?', '["Both blocks lose about a fifth of their oil, since the field total falls.", "The east block falls from 52 cells to 18 and loses 86 percent of its oil.", "The east block loses roughly 10 percent, in proportion to the 10 m change.", "The east block is unchanged, since its wells were already dry at 1560 m."]'::jsonb, 1, 'Raising a contact removes area and column at the same time, and the two compound. The east block''s mean column at 1560 m was only 8.06 m, so a 10 m rise takes more than most cells had.'),
  ('reservoircalc', 'intermediate', 'module', 'm05-two-blocks-two-contacts', 4, 'Why does the west block not move when the east block''s contact is changed?', '["Because the west block was clipped against its own contact.", "Because the west block lies above both contacts everywhere.", "Because contacts are applied after the volumes have already been summed for each block.", "Because the two blocks share a mask, which is decided by geometry alone."]'::jsonb, 0, 'Each block is booked independently against the contact it was given. That independence is the whole point of a partition and it is why a field total now carries two assumptions.'),
  ('reservoircalc', 'intermediate', 'module', 'm05-two-blocks-two-contacts', 5, 'Which block responds most violently to a change in its own contact, and why?', '["The larger block, with more cells for the change to act on.", "The block holding the crest, because its columns are tallest.", "The thinner block, because a 10 m rise is more than most of its cells had.", "Both equally, since the contact moves the same distance."]'::jsonb, 2, 'The east block''s mean column at 1560 m is 8.06 m, so raising its contact by 10 m leaves 18 of its 52 cells. Thin compartments are also the ones whose contacts are least constrained.'),
  ('reservoircalc', 'intermediate', 'module', 'm05-two-blocks-two-contacts', 6, 'Set the east contact to 1570 m. What does the east block become?', '["73 cells and 5.810977 MMstb, about two and a half times its booking at 1560 m.", "52 cells and 2.283591 MMstb, since deepening a contact adds column but not area.", "18 cells and 0.327859 MMstb, since the deeper contact drowns the flank.", "117 cells and 9.855617 MMstb, matching the west block."]'::jsonb, 0, 'Deepening adds area at the edges and column everywhere at once, so the response compounds upward just as raising it compounds downward.'),
  ('reservoircalc', 'intermediate', 'module', 'm05-two-blocks-two-contacts', 7, 'Why is the contact response not symmetric about 1560 m in the east block?', '["Because the mask limits how far the mapped area can extend eastward.", "Because the block''s mean column is closer to the downside than to the upside.", "Because deepening floods new area on a broad gentle flank while raising simply removes column.", "Because the properties are applied after the contact, so they scale the two directions differently."]'::jsonb, 2, 'Going up 10 m costs 1.955732 MMstb and going down 10 m gains 3.527386 MMstb. A contact sensitivity on a flank cannot be quoted as a plus or minus.'),
  ('reservoircalc', 'intermediate', 'module', 'm05-two-blocks-two-contacts', 8, 'With the east contact at 1570 m, what does the model say about Ekene-2?', '["That it is still dry, since its top at 1565 m lies below the contact.", "That it found oil, which contradicts the well result.", "That it lies outside the eastern compartment at that contact.", "That its top pick must be wrong by at least 5 m."]'::jsonb, 1, 'Ekene-2 tops at 1565 m and is dry. A contact at 1570 m would have put that well in the oil leg, so the 1570 m case is ruled out by an observation already in hand.'),
  ('reservoircalc', 'intermediate', 'module', 'm05-two-blocks-two-contacts', 9, 'What bounds the eastern contact using the Ekene well data alone?', '["Oil at Ekene-6 above and water at Ekene-2 at 1565 m below, so roughly 1546 to 1565 m.", "The mapped crest at 1539.72 m above and the deepest base pick at 1615 m below.", "Nothing. No eastern well constrains the eastern contact.", "The western contact of 1560 m, since a sealing fault cannot support a large difference."]'::jsonb, 0, 'It took a dry well to produce the upper bound, which is the most useful thing Ekene-2 does in this tier. Over that range the eastern booking runs from very little to about 2.9 MMstb.'),
  ('reservoircalc', 'intermediate', 'module', 'm05-two-blocks-two-contacts', 10, 'What does the field sum become when the east block is booked at 1570 m and the west at 1560 m?', '["12.139208 MMstb, since the field total is invariant.", "10.183477 MMstb, a fall of 16 percent.", "15.666594 MMstb, a rise of 29 percent.", "22.044451 MMstb, which is the whole field at 1570 m."]'::jsonb, 2, 'Every barrel of the difference is in the east block. A partitioned field carries one contact assumption per compartment and the total inherits all of them.'),
  ('reservoircalc', 'intermediate', 'module', 'm05-two-blocks-two-contacts', 11, 'What is wrong with reporting a partitioned field as a single number?', '["It hides that the sum is arithmetic across compartments that no well can drain together.", "It cannot be checked against the compartment volumes without the cell counts.", "It overstates the field, since compartments always lose oil along their boundaries.", "It is only defensible when both compartments were booked at the same contact."]'::jsonb, 0, 'The single number is three claims wearing one figure: a west booking, an east booking, and the assertion that adding them describes something drainable.'),
  ('reservoircalc', 'intermediate', 'module', 'm05-two-blocks-two-contacts', 12, 'Which four items belong in the summary of a compartmentalised booking?', '["The fault position, the seal evidence, the well count in each block and the recovery factor.", "The field total, the cell count, the mean column and the contact.", "The gross rock volume of each block, the properties, the chain and the total.", "Each compartment with its contact, the labelled sum, the partition assumptions and the map''s relationship to the fault."]'::jsonb, 3, 'All four are quantities this tier computes. A report giving block volumes to six figures and mentioning none of them is quoting a precision it has not earned.'),
  ('reservoircalc', 'intermediate', 'module', 'm05-two-blocks-two-contacts', 13, 'A pressure survey measures the eastern contact at 1552 m. What follows?', '["The eastern booking rises above 2.283591 MMstb and the compartment becomes a target.", "The eastern booking collapses to about half a million barrels.", "The western booking must be revised to match it, since contacts equilibrate across a seal.", "The partition must be rebuilt, since a measured contact changes the block labels."]'::jsonb, 1, 'Reading between the 1550 and 1560 m cases puts it a little above 0.327859 MMstb. The measurement was worth more than any amount of further mapping, which is a conclusion a volumetric study should be willing to reach about itself.'),
  ('reservoircalc', 'intermediate', 'module', 'm05-two-blocks-two-contacts', 14, 'Both blocks are booked at 1550 m. Why is the west block''s response gentler than the east''s?', '["Because the west block was booked against a deeper base surface.", "Because its structure is broad and shallow, so few cells fall below the new contact.", "Because it holds the crest, which is unaffected by a 10 m change.", "Because its mean oil column exceeds the 10 m change, so not one of its cells is lost."]'::jsonb, 1, 'The west keeps 110 of its 117 cells while losing 10 m of column from each, so it loses on one count. The east loses cells and column together.'),
  ('reservoircalc', 'intermediate', 'module', 'm05-two-blocks-two-contacts', 15, 'What can this tier compute about compartment contacts, and what can it not?', '["It can compute neither, since contacts belong to the tier below.", "It can bound the contact from the map and cannot compute the consequences.", "It can compute both, given the well picks and the fault position.", "It can compute the consequences and cannot supply the contact."]'::jsonb, 3, 'The consequences are arithmetic. The contact comes from pressure and fluid data, which the volumetric model never sees.'),
  ('reservoircalc', 'intermediate', 'module', 'm06-the-compartment-workflow', 1, 'What is the first step in the compartment workflow?', '["Assign a block label to every node in the frame, deciding the boundary convention.", "Fix the fault geometry, including its position and, where the reservoir is thick, its dip.", "Build the structural surfaces from the well picks on the frame chosen for the study.", "Establish that the field is compartmentalised."]'::jsonb, 3, 'Volumetrics cannot establish a seal. Without evidence a partition is a hypothesis and should be labelled as one, since the output looks identical whether or not the fault seals.'),
  ('reservoircalc', 'intermediate', 'module', 'm06-the-compartment-workflow', 2, 'Which step of the workflow carries the largest number at Ekene when it fails?', '["Choosing a contact for each compartment rather than one for the field.", "Building the surfaces, which at Ekene were gridded without knowledge of the fault.", "Labelling the grid, where the boundary convention decides who owns the fault column.", "Fixing the fault geometry, whose position uncertainty is at least 100 m."]'::jsonb, 1, 'Removing the single eastern well that found oil takes 1.989889 MMstb off the west block, which is more than the fault position and the tie break convention are worth together.'),
  ('reservoircalc', 'intermediate', 'module', 'm06-the-compartment-workflow', 3, 'Steps three and four, gridding and labelling, can be run in either order. Why does the order still matter?', '["Because labelling first would let the gridder restrict each well to its own block.", "Because the two steps write to the same arrays and the second would overwrite the first.", "Because the field total is accumulated during gridding rather than during labelling.", "Because the contact must be applied between them for the cell count to be correct."]'::jsonb, 0, 'Mechanically the result is identical, since labelling does not change depths and gridding does not read labels. If you intend the compartments to be independent, that intention belongs in the gridding.'),
  ('reservoircalc', 'intermediate', 'module', 'm06-the-compartment-workflow', 4, 'Which check verifies that every oil bearing cell belongs to exactly one block?', '["Volume closure, comparing the block volumes against the field volume.", "Invariance, confirming the field total holds as the fault position is stepped.", "Completeness, adding the block cell counts and comparing to the field count.", "Label coverage, confirming every node in the frame carries a label."]'::jsonb, 2, 'At Ekene, 117 plus 52 gives 169. Cells belonging to no block, or to two, break that sum immediately.'),
  ('reservoircalc', 'intermediate', 'module', 'm06-the-compartment-workflow', 5, 'Which two failures pass every partition check cleanly?', '["A fault position error, and a contact that is unsupported by evidence.", "A cell assigned to no block, and a contact applied inconsistently.", "A label array that does not cover the frame, and a double counted cell.", "A cell in the wrong block, and a fault that does not seal."]'::jsonb, 3, 'Moving a cell from one block to another leaves the total unchanged, and the arithmetic of a partition is identical whether or not the partition is physically real.'),
  ('reservoircalc', 'intermediate', 'module', 'm06-the-compartment-workflow', 6, 'How do you catch a boundary drawn in the wrong place, given that the arithmetic checks cannot?', '["By comparing the block volumes against an independent estimate of each compartment.", "By looking at the map and confirming the fault trace runs where you think it does.", "By stepping the fault and confirming that the field total does not move.", "By checking that each block contains at least one well that found oil."]'::jsonb, 1, 'A boundary in the wrong place is a self consistent partition of the wrong thing. The panel draws the fault trace through the boundary the labels actually test, so what you see is what the engine did.'),
  ('reservoircalc', 'intermediate', 'module', 'm06-the-compartment-workflow', 7, 'Which Associate tier check now has to be applied per block rather than to the field?', '["That the chain multiplies out from gross rock volume through to STOIIP.", "That the mapped crest is shallower than the shallowest well pick.", "That every live node lies within the extrapolation limit of a well.", "That the contact used is supported by a measurement rather than an assumption."]'::jsonb, 0, 'An error in one block''s chain is invisible in a field total that was accumulated separately, so the multiplication has to be verified for each block.'),
  ('reservoircalc', 'intermediate', 'module', 'm06-the-compartment-workflow', 8, 'What settings does the capstone ask for?', '["A fault at 1900 m with both blocks booked at the 1560 m contact.", "A fault at 1800 m with the west at 1560 m and the east at 1550 m.", "A fault at 1800 m with each block booked at its own measured contact.", "A fault at 1800 m with both blocks booked at the 1560 m contact."]'::jsonb, 3, 'That is the panel''s default configuration, so a learner who has not moved anything is already there. The two blocks must sum to the field total booked at the Associate tier.'),
  ('reservoircalc', 'intermediate', 'module', 'm06-the-compartment-workflow', 9, 'Which two of the six capstone values are graded with no tolerance at all?', '["The two gross rock volumes, since they depend only on geometry.", "The two cell counts, since a count is either right or wrong.", "The two STOIIP values, since they are what a decision maker reads.", "The west cell count and the west gross rock volume."]'::jsonb, 1, 'A value of 116 or 118 scores nothing. The gross rock volumes carry tolerances of 0.05 and 0.02 and the STOIIP values the same.'),
  ('reservoircalc', 'intermediate', 'module', 'm06-the-compartment-workflow', 10, 'Which pair of capstone values tests the partition itself, before any property enters?', '["The two STOIIP values, which are the end of the chain.", "The two cell counts, which test only that the same cells were divided.", "The two gross rock volumes, which depend on geometry alone.", "The two mean oil columns, which explain the volume split."]'::jsonb, 2, 'Since the properties are the same in both blocks, the STOIIP values carry no information the gross rock volumes do not, and they are asked for because they are what a decision maker reads.'),
  ('reservoircalc', 'intermediate', 'module', 'm06-the-compartment-workflow', 11, 'Which three sums should be checked before submitting the capstone?', '["The cell counts to 169, the gross rock volumes to 22.269036, the STOIIP values to 12.139208.", "The cell counts to 201, the gross rock volumes to 22.269036, the STOIIP values to 12.139208.", "The cell counts to 169, the gross rock volumes to 17.815229, the STOIIP values to 12.139208.", "The mean columns to 13.176944, the cell counts to 169, the STOIIP values to 12.139208."]'::jsonb, 0, '201 is the live node count rather than the oil bearing count, and 17.815229 is the field net volume rather than its gross rock volume.'),
  ('reservoircalc', 'intermediate', 'module', 'm06-the-compartment-workflow', 12, 'What is the most frequent error on this capstone?', '["Reading the block values with an east contact left at 1550 m from an earlier module.", "Reading the field values from the panel tiles instead of the two block values.", "Applying the chain to each block with different properties.", "Assigning the boundary column to the west block instead of the east."]'::jsonb, 0, 'The west values are then correct and both east values are wrong, and since the west is right the error is easy to miss. The three sum checks catch it immediately.'),
  ('reservoircalc', 'intermediate', 'module', 'm06-the-compartment-workflow', 13, 'Which finding from this tier is most worth carrying into any partitioned model you meet?', '["That the blocks must reproduce the field total to about fifteen significant figures.", "That area and barrels split in different proportions when one block holds the crest.", "That the map was built before the fault was mentioned, so each block borrows control.", "That a tie break on the boundary column is worth 0.901423 MMstb at Ekene."]'::jsonb, 2, 'At Ekene it is worth 1.989889 MMstb on the west block, more than the fault position and the tie break convention combined, and it is the finding least likely to appear in a report.'),
  ('reservoircalc', 'intermediate', 'module', 'm06-the-compartment-workflow', 14, 'What does the Expert tier change relative to this one?', '["It replaces the constant porosity with a value at every node.", "It rebuilds the structural surfaces so that they honour the fault as a real discontinuity.", "It books each compartment against its own measured contact.", "It carries the compartment volumes through to recoverable reserves."]'::jsonb, 0, 'The same contact, the same map and the same chain, with a grid where there was a number. The fault is set aside so that the property model is the only thing that changes.'),
  ('reservoircalc', 'intermediate', 'module', 'm06-the-compartment-workflow', 15, 'How does the Expert tier''s uplift compare with the conventions priced in this tier?', '["It is larger than both, at 0.656868 MMstb against 0.901423 MMstb each.", "It is smaller than both, and most of it is not spatial.", "It is the same size as the cross fault control, at about 2 MMstb.", "It cannot be compared, since it moves the field total and they do not."]'::jsonb, 1, 'A whole tier is built on a quantity that this tier''s labelling conventions outweigh, and the larger part of it comes from something simpler than a property model.'),
  ('reservoircalc', 'intermediate', 'final', null, 1, 'Which set of six values is the Ekene fault block capstone answer key?', '["117, 52, 18.079852294921874, 4.189183349609375, 9.85561714769438 and 2.2835909598023787.", "130, 39, 19.733488, 2.535547, 10.757040217893243 and 1.38216788960352.", "117, 52, 14.463882051466133, 3.3513467296264574, 9.85561714769438 and 2.2835909598023787.", "169, 0, 22.26903564453125, 0, 12.139208107496763 and 0."]'::jsonb, 0, 'The set beginning 130 and 39 is the same fault with the boundary column assigned west, the set with 14.463882 and 3.351347 gives net volumes rather than gross rock volumes, and the set ending in zero is the unpartitioned field.'),
  ('reservoircalc', 'intermediate', 'final', null, 2, 'A partition is applied to a field. What happens to the oil in place?', '["It falls by the volume of the cells that straddle the fault plane.", "Nothing, since the rock and its oil have not moved.", "It rises, because each compartment can support its own oil column.", "It becomes undefined until each compartment has a contact."]'::jsonb, 1, 'Volumes add and decisions do not. What changes is drainage, pressure behaviour and the contact assumption, none of which is a volume.'),
  ('reservoircalc', 'intermediate', 'final', null, 3, 'What is the single new instruction that turns the Associate model into the Professional one?', '["Every node is given a block label and the volumes are summed per label.", "Each compartment is booked against a contact established in its own wells.", "The surfaces are rebuilt so that they honour the fault as a discontinuity.", "The properties are averaged separately over each side of the fault."]'::jsonb, 0, 'The map, the contact, the properties and the chain are all unchanged. The consequences are not mechanical, which is why the tier takes six modules.'),
  ('reservoircalc', 'intermediate', 'final', null, 4, 'Why is a strict inequality on the fault easting a decision rather than a detail?', '["Because it changes the field total by the volume of the boundary column.", "Because it decides which block owns 13 cells worth 0.901423 MMstb.", "Because it determines whether the fault is treated as sealing or leaking.", "Because it fixes the number of live nodes in each of the two blocks."]'::jsonb, 1, 'The field total is untouched, which is exactly why the transfer is easy to miss. The rock straddles a plane of zero width and the model has to put it somewhere.'),
  ('reservoircalc', 'intermediate', 'final', null, 5, 'Which is larger at Ekene: the tie break convention on the boundary column, or the entire Expert tier property model?', '["The property model, at 0.656868 against 0.901423 MMstb.", "They are equal, at about 0.9 MMstb each.", "The tie break convention, at 0.901423 against 0.656868 MMstb.", "Neither can be compared, since one is a transfer and the other is an uplift."]'::jsonb, 2, 'A comparison operator in a labelling routine outweighs the whole property model a tier is built around, and only one of the two normally gets a mention in a report.'),
  ('reservoircalc', 'intermediate', 'final', null, 6, 'How many of the 500 nodes in the Ekene frame carry a block label?', '["280, which is the number of nodes west of the fault.", "201, which is the number of live nodes.", "169, which is the number of oil bearing cells at the contact.", "All 500, including dead nodes and nodes carrying no oil."]'::jsonb, 3, 'A label is a property of a position, and a position has a block whether or not anything was mapped there. Dead nodes never reach the accumulation step, so their labels are never used.'),
  ('reservoircalc', 'intermediate', 'final', null, 7, 'Which three tests decide whether a node contributes to a block''s volume?', '["Whether it is live, whether it carries an oil column, and which block its label names.", "Whether it is inside the hull, within 800 m of a well, and west of the fault.", "Whether it is live, whether it is within the extrapolation limit, and whether it holds oil.", "Whether its top is above the contact, its base below it, and its label valid."]'::jsonb, 0, 'The three are independent, which is why changing one has a predictable and limited effect and why reading them together tells you which part of the model changed.'),
  ('reservoircalc', 'intermediate', 'final', null, 8, 'Why does the live area at Ekene extend across the fault trace in both directions?', '["Because the fault has no displacement, so the surfaces are continuous.", "Because the mask reads well positions only and knows nothing about faults.", "Because the extrapolation limit was set wider than the fault spacing.", "Because both blocks contain three wells, so both sides are equally controlled."]'::jsonb, 1, 'The gridder tests a distance and nothing else. The mask is doing its job, and it becomes a problem only when a partition is laid over the top.'),
  ('reservoircalc', 'intermediate', 'final', null, 9, 'Stepping the fault across the whole range, what must never change?', '["The mean oil column of each block.", "The number of wells in each block.", "The field cell count and the field total.", "The share of barrels held by the west block."]'::jsonb, 2, 'Moving the fault only relabels cells. A total that moves during a fault sweep means cells are being counted in more than one block.'),
  ('reservoircalc', 'intermediate', 'final', null, 10, 'At a fault of 1500 m the split is 78 and 91 cells; at 1600 m it is 91 and 78. What does that show?', '["That the barrels split evenly somewhere between those two positions.", "That the sweep is linear in cell count across the full range.", "That both positions book the same volume in the west block.", "That the accumulation is nearly symmetric in area about 1550 m."]'::jsonb, 3, 'The mirror is in area only. The barrels split evenly nearer 1450 m, because the western cells carry taller columns.'),
  ('reservoircalc', 'intermediate', 'final', null, 11, 'Which rows of a partitioned chain add to the field total bit for bit?', '["Cell count, gross rock volume and net volume.", "Every row, since a partition is exact arithmetic on the same set of cells.", "Cell count only, since integer addition alone is exact.", "Cell count, gross rock volume, net volume and pore volume."]'::jsonb, 0, 'Pore volume, hydrocarbon pore volume and STOIIP differ in the last bits, because the chain stops being exactly representable once it multiplies by a float32 porosity.'),
  ('reservoircalc', 'intermediate', 'final', null, 12, 'Why is the field total not simply the sum of the block totals?', '["Because it is computed before the labels are applied.", "Because it is accumulated in its own register as the node walk proceeds.", "Because it includes cells that fall in no block.", "Because it is derived from the field mean oil column."]'::jsonb, 1, 'Each node''s contribution is added twice, once to its block and once to the total. That makes the closure check a genuine comparison against an independent accumulation.'),
  ('reservoircalc', 'intermediate', 'final', null, 13, 'A partition check agrees to only six significant figures. What does that tell you?', '["That the accumulation noise is normal for a model of this size.", "That the blocks were booked against different contacts.", "That something structural is wrong rather than imprecise.", "That the field total was rounded before being reported."]'::jsonb, 2, 'The genuine accumulation difference at Ekene is 5 parts in 10^15. A discrepancy at six figures is thousands of times larger and points to a lost or double counted cell.'),
  ('reservoircalc', 'intermediate', 'final', null, 14, 'The Ekene cells split 2.25 to 1 and the barrels 4.32 to 1. What is the ratio of the mean oil columns?', '["1.35 to 1, which is the ratio of the two maximum columns.", "2.25 to 1, since the same properties apply to both blocks.", "4.32 to 1, since volume and column are proportional.", "1.918 to 1, whose product with 2.25 is the barrel ratio."]'::jsonb, 3, 'Mean columns of 15.452865 m and 8.056122 m give 1.918, and 2.25 times 1.918 gives 4.316. The west block wins twice: more cells, and thicker ones.'),
  ('reservoircalc', 'intermediate', 'final', null, 15, 'Why can no step below gross rock volume change the ratio between two blocks?', '["Because the chain applies the same four constants to both blocks.", "Because the properties are re-averaged over each block before the chain runs.", "Because net to gross is the only property that varies between blocks.", "Because the ratio is fixed by the cell counts, which the chain cannot alter."]'::jsonb, 0, 'Multiplying both blocks by the same constants preserves their ratio, so the whole difference between 2.25 and 4.32 is already present in the gross rock volume.'),
  ('reservoircalc', 'intermediate', 'final', null, 16, 'What does a gap between a block''s share of cells and its share of barrels measure?', '["The uncertainty in the position of the fault between the blocks.", "The extent to which the two blocks hold different shapes of rock.", "The error introduced by assigning the boundary column to one side.", "The difference in net to gross between the two compartments."]'::jsonb, 1, 'At Ekene the gap is twelve percentage points, 69.2 against 81.2. It is entirely a mean column difference, since the properties are identical in both blocks.'),
  ('reservoircalc', 'intermediate', 'final', null, 17, 'Which block holds the field''s maximum oil column of 20.2818603515625 m?', '["The east block, in the thick area around Ekene-6.", "Neither, since the maximum lies on the boundary column.", "The west block, which therefore holds the crest.", "Whichever block the fault is placed to include."]'::jsonb, 2, 'The east block''s own maximum is 16.5079345703125 m, 19 percent shorter. At a fault of 1500 m the crest would change hands, and it travels with the barrels.'),
  ('reservoircalc', 'intermediate', 'final', null, 18, 'What does a block''s maximum column divided by its mean column tell you?', '["The uncertainty on that block''s booking.", "How much the block would change if the contact moved.", "The ratio of its crestal area to its flank area.", "How uniform the block is."]'::jsonb, 3, 'The east block reads 2.05 and the west 1.31, so a single eastern well placed away from the thick area near Ekene-6 would find far less than the block maximum suggests.'),
  ('reservoircalc', 'intermediate', 'final', null, 19, 'In what order were the surfaces, the contact and the fault labels applied at Ekene?', '["Surfaces, then the contact, then the fault labels.", "Fault labels, then surfaces gridded within each block, then the contact.", "Surfaces, then the fault labels, then the contact.", "The contact was applied to the picks before the surfaces were gridded."]'::jsonb, 0, 'At no point did the surface construction know about the fault, so the interpolator ran straight across the fault trace as though the rock were continuous.'),
  ('reservoircalc', 'intermediate', 'final', null, 20, 'Remove Ekene-6 and regrid. What happens to the west block?', '["It loses 34 cells while its volume holds.", "It falls to 7.865728 MMstb with its 117 cells intact.", "It is unchanged, since Ekene-6 lies east of the fault.", "It falls by 0.901423 MMstb, the value of the boundary column."]'::jsonb, 1, 'A fifth of the western compartment''s booked oil exists only because a well on the far side of a sealing fault pulled the mapped surface up on that side.'),
  ('reservoircalc', 'intermediate', 'final', null, 21, 'Why does removing a well change a block''s volume without changing its cell count?', '["Because the contact was held fixed while the surfaces were rebuilt.", "Because the removed well lay outside the block being measured.", "Because liveness reads well positions and volume reads mapped depths.", "Because the extrapolation limit compensates for the lost control."]'::jsonb, 2, 'Cell counts move when geometry moves and volumes move when depths move. Ekene-6 was never the reason any western node was live; it was supplying depth.'),
  ('reservoircalc', 'intermediate', 'final', null, 22, 'Grid the Ekene surfaces from the three western wells only. What is the result?', '["The west block grows, since eastern picks had been pulling its surface down.", "The west block is unchanged and the east block falls to nothing.", "Both blocks shrink in proportion to the control removed.", "The west block holds 48 cells and 3.406726 MMstb, and the east none."]'::jsonb, 3, 'More than half of the west block''s mapped area is live only because eastern wells are within reach of it. That is the opposite extreme from the shared map, and the truth is between the two.'),
  ('reservoircalc', 'intermediate', 'final', null, 23, 'Two features made the Ekene-6 effect large. Which two?', '["That it lies 100 m from the fault, and that its pick is the second shallowest.", "That it is the only eastern well with oil, and that it lies on the hull boundary.", "That it lies far from the other eastern wells, and that its base pick is deep.", "That it lies on a grid node, and that it sits high on the structure."]'::jsonb, 0, 'Proximity makes its influence on nodes just west strong, and a shallow control point lets the fitted surface sag over a wide area when it is removed.'),
  ('reservoircalc', 'intermediate', 'final', null, 24, 'What do the two dry Ekene wells contribute?', '["Nothing, since a dry well cannot inform a volumetric estimate.", "They define the eastern flank of the structure and so constrain the surfaces.", "They fix the eastern contact, since water was found at their tops.", "They confirm that the eastern compartment holds no economic oil."]'::jsonb, 1, 'Without them the map would not know how fast the surface falls away eastward. What they cannot do is confirm that the eastern compartment holds oil, which only Ekene-6 does.'),
  ('reservoircalc', 'intermediate', 'final', null, 25, 'Which statement about the eastern compartment''s evidence is correct?', '["It rests on three wells, all of which constrain its surface and its oil.", "It rests on two oil bearing wells and one dry well on the far flank.", "It rests on one oil bearing well at the compartment''s extreme edge.", "It rests on no wells at all, since all three eastern wells are dry."]'::jsonb, 2, 'Ekene-6 is 100 m from the fault. Its booking of 2.283591 MMstb and the west''s 9.855617 MMstb are quoted to the same precision and are not remotely equally certain.'),
  ('reservoircalc', 'intermediate', 'final', null, 26, 'A fault dips 55 degrees through a 250 m reservoir on a 100 m grid. Is a vertical approximation defensible?', '["Yes, since the fault plane is still a single surface in map view.", "No, since a dipping fault cannot be represented by a label array at all.", "Yes, provided the displacement is smaller than the reservoir thickness.", "No, since the trace moves 175 m between top and base, nearly two cells."]'::jsonb, 3, 'The test is the ratio of reservoir thickness to cell size. Through Ekene''s 30 m the same geometry moves 17 m, which is a fifth of a cell and genuinely negligible.'),
  ('reservoircalc', 'intermediate', 'final', null, 27, 'Why do compartments that never communicated have no obligation to share a contact?', '["Because each has had its own charge history, trap geometry and pressure regime.", "Because the fault plane holds its own fluid system between them.", "Because a mapped surface steps across a displaced fault.", "Because sealing faults always juxtapose different reservoir units."]'::jsonb, 0, 'The contact is the visible record of an independent history. If two compartments do share one, that is itself a finding rather than a default.'),
  ('reservoircalc', 'intermediate', 'final', null, 28, 'Take the east contact from 1560 m to 1550 m. What happens to the east block?', '["It falls by about 10 percent, in proportion to the change.", "It falls from 52 to 18 cells and loses 86 percent of its oil.", "It is unchanged, since both its wells were already dry.", "It falls from 52 to 39 cells, matching a one column fault move."]'::jsonb, 1, 'Raising a contact removes area and column together and the two compound. A block whose mean column is 8.06 m cannot survive a 10 m rise with much left.'),
  ('reservoircalc', 'intermediate', 'final', null, 29, 'Why is the east block''s contact response asymmetric about 1560 m?', '["Because the mask limits how far the mapped area can extend eastward.", "Because the properties scale the two directions differently.", "Because deepening floods new area on a broad gentle flank while raising only removes column.", "Because the western contact was held fixed throughout."]'::jsonb, 2, 'Going up 10 m costs 1.955732 MMstb and going down 10 m gains 3.527386 MMstb. On a flank the downside is bounded by the oil running out and the upside only by the spill point.'),
  ('reservoircalc', 'intermediate', 'final', null, 30, 'An east contact of 1570 m is proposed. What rules it out?', '["The mapped crest at 1539.72 m, which is shallower than that contact.", "The extrapolation limit, which does not reach that far east.", "The western contact of 1560 m, which a sealing fault cannot differ from by 10 m.", "Ekene-2, which tops at 1565 m and is dry."]'::jsonb, 3, 'It took a dry well to produce the upper bound, which is the most useful thing Ekene-2 does in this tier. The eastern contact lies between roughly 1546 and 1565 m.'),
  ('reservoircalc', 'intermediate', 'final', null, 31, 'What happens to the field sum when the east block is booked at 1570 m and the west at 1560 m?', '["It rises to 15.666594 MMstb, a gain of 29 percent, all of it in the east.", "It holds at 12.139208 MMstb, since the field total is invariant.", "It falls to 10.183477 MMstb, since the deeper contact drowns the flank.", "It rises to 22.044451 MMstb, the whole field at 1570 m."]'::jsonb, 0, 'A partitioned field carries one contact assumption per compartment, and the total inherits all of them. That is the point at which a single field number stops being reportable.'),
  ('reservoircalc', 'intermediate', 'final', null, 32, 'Which step of the compartment workflow cannot be answered by volumetrics at all?', '["Choosing a contact for each compartment.", "Establishing that the fault seals.", "Fixing the fault position and its uncertainty.", "Deciding the boundary convention on the fault column."]'::jsonb, 1, 'The evidence is pressure differences, differing contacts, production interference, or a juxtaposition argument. Without it, a partition is a hypothesis.'),
  ('reservoircalc', 'intermediate', 'final', null, 33, 'Which two failures pass completeness, closure, invariance and coverage?', '["A cell in no block, and a double counted cell.", "A label array that stops short of the frame, and an inconsistent contact.", "A cell in the wrong block, and a fault that does not seal.", "A fault position error, and a wrongly assigned boundary column."]'::jsonb, 2, 'Moving a cell between blocks leaves the sum unchanged, and the arithmetic of a partition is identical whether or not it is physically real.'),
  ('reservoircalc', 'intermediate', 'final', null, 34, 'Which check catches a boundary drawn two cells away from where the report says it is?', '["Volume closure, since the block volumes would not add.", "Completeness, since some cells would fall in no block.", "Invariance, since the field total would move.", "Looking at the map, since no arithmetic check can see it."]'::jsonb, 3, 'A boundary in the wrong place is a self consistent partition of the wrong thing. At Ekene two columns would be roughly 26 cells and on the order of 1.8 MMstb.'),
  ('reservoircalc', 'intermediate', 'final', null, 35, 'Which Associate tier check now has to be run once per block?', '["That the chain multiplies out from gross rock volume through to STOIIP.", "That the mapped crest lies above the shallowest well pick.", "That every live node lies within the extrapolation limit.", "That the contact is supported by a measurement."]'::jsonb, 0, 'An error in one block''s chain is invisible in a field total that was accumulated in its own register, so the multiplication has to be verified per block.'),
  ('reservoircalc', 'intermediate', 'final', null, 36, 'Which two of the six capstone fields are graded exactly, with no tolerance?', '["The two gross rock volumes.", "The two cell counts.", "The two STOIIP values.", "The west cell count and the west STOIIP."]'::jsonb, 1, 'A count is either right or wrong. The gross rock volumes carry tolerances of 0.05 and 0.02 and the STOIIP values the same.'),
  ('reservoircalc', 'intermediate', 'final', null, 37, 'Which three sums check a capstone submission?', '["Cells to 169, gross rock volumes to 17.815229, STOIIP to 12.139208.", "Cells to 201, gross rock volumes to 22.269036, STOIIP to 12.139208.", "Cells to 169, gross rock volumes to 22.269036, STOIIP to 12.139208.", "Cells to 169, mean columns to 13.176944, STOIIP to 12.139208."]'::jsonb, 2, '201 is the live node count rather than the oil bearing count, and 17.815229 is the field net volume rather than its gross rock volume.'),
  ('reservoircalc', 'intermediate', 'final', null, 38, 'Rank these Ekene quantities from largest to smallest.', '["Property model, contact 10 m, cross fault control, fault position.", "Cross fault control, contact 10 m, property model, fault position.", "Contact 10 m, fault position, cross fault control, property model.", "Contact 10 m, cross fault control, fault position, property model."]'::jsonb, 3, 'Roughly 8 to 10 MMstb, then 1.989889, then 0.901423, then 0.656868. The contact dominates by an order of magnitude, which the Associate tier established and nothing since has challenged.'),
  ('reservoircalc', 'intermediate', 'final', null, 39, 'A compartment holds 2.283591 MMstb at an assumed contact and its data allows the contact to range over 19 m. What should the study conclude?', '["That the decision cannot be made from the volumetric model, and a contact measurement is needed.", "That the compartment is a target, since the booking exceeds two million barrels.", "That the compartment should be booked at the midpoint of the allowed range.", "That the partition should be redone with the fault moved to include more oil."]'::jsonb, 0, 'Over the allowed range the booking runs from very little to about 2.9 MMstb, and no well changes state across it. Reaching that conclusion about itself is a legitimate output for a volumetric study.'),
  ('reservoircalc', 'intermediate', 'final', null, 40, 'Why does the smaller compartment usually carry the larger relative uncertainty?', '["Because it has fewer wells and therefore weaker control.", "Because a given absolute transfer is a larger fraction of a smaller block.", "Because its cells lie closer to the extrapolation limit.", "Because its mean column is shorter, so each cell is less certain."]'::jsonb, 1, 'A 100 m fault move is worth about 0.9 MMstb either way: roughly 10 percent of the Ekene west block and about 40 percent of the east. The compartment most in doubt is usually the one whose economics are most marginal.'),
  ('reservoircalc', 'intermediate', 'final', null, 41, 'Which finding of this tier is least likely to appear in a report and most worth reporting?', '["That the blocks reproduce the field total to fifteen significant figures.", "That the west block holds 81.2 percent of the barrels.", "That the surfaces were gridded without knowledge of the fault.", "That the two blocks contain three wells each."]'::jsonb, 2, 'At Ekene it is worth 1.989889 MMstb on the west block, more than the fault position and the tie break convention together, and the reader has no way to discover it from the numbers alone.'),
  ('reservoircalc', 'intermediate', 'final', null, 42, 'What does the Expert tier do that this tier does not, and how large is it?', '["It books each compartment against its own contact, worth up to 3.5 MMstb.", "It carries the compartment volumes through to recoverable reserves.", "It rebuilds the surfaces to honour the fault, worth 1.989889 MMstb.", "It lets porosity vary across the field, worth 0.656868 MMstb."]'::jsonb, 3, 'That uplift is smaller than the conventions this tier priced, and most of it turns out not to be spatial at all, which the Expert tier decomposes.');
